// One-bit OR of two 3-bit vectors (the bitwise form)
module TopModule(
    input  [2:0] a,
    input  [2:0] b,
    output [2:0] out_or_bitwise,
    output       out_or_logical,
    output [5:0] out_not
);
    wire [2:0] or0_out;
    wire       or1_out;
    wire [2:0] not0_out, not1_out;
    or #(1) or0 (or0_out, a, b);
    assign out_or_bitwise = or0_out;
    assign out_or_logical = (a != 3'b0) || (b != 3'b0);
    not #(1) not0 (not0_out, b);
    not #(1) not1 (not1_out, a);
    assign out_not = {not0_out, not1_out};
endmodule

