// One-shot capture: goes high for one clock cycle, then goes low.
module CaptureOneShot (
    input  clk,
    input  reset,
    input  in,
    output reg out
);
    reg last_in;
    reg first_transition_this_cycle;
    always @(posedge clk) begin
        if (reset) begin
            out <= 1'b0;
            first_transition_this_cycle <= 1'b0;
        end else begin
            if (in != last_in && !first_transition_this_cycle) begin
                out <= 1'b1;
                first_transition_this_cycle <= 1'b1;
            end
            last_in <= in;
        end
    end
endmodule

