// Moore-type FSM, one hot state encoding
module TopModule(input clk, input reset, input in, output reg disc, output reg flag, output reg err);
  reg [2:0] state, next_state;
  reg [3:0] cnt;
  always @(*) begin
    case (state)
      3'b000: next_state = in ? 3'b001 : 3'b000;
      3'b001: next_state = in ? 3'b010 : 3'b000;
      3'b010: next_state = in ? 3'b011 : 3'b000;
      3'b011: next_state = in ? 3'b100 : 3'b000;
      3'b100: next_state = in ? 3'b101 : 3'b000;
      3'b101: next_state = in ? 3'b110 : 3'b000;
      3'b110: next_state = in ? 3'b111 : 3'b000;
      3'b111: next_state = in ? 3'b000 : 3'b111;
    endcase
  end
  always @(posedge clk) begin
    if (reset) begin
      state <= 3'b000;
      cnt <= 4'b0;
      disc <= 1'b0;
      flag <= 1'b0;
      err <= 1'b0;
    end else begin
      state <= next_state;
      cnt <= (state == 3'b111) ? cnt + 4'b1 : 4'b0;
      disc <= (state == 3'b000) & in;
      flag <= (state == 3'b000) & ~in;
      err <= (cnt >= 4'b1111);
    end
  end
endmodule

