// Moore-type finite state machine. Same function as the synchronous HDLC
// framing: detect the three sequences required for framing and discard the
// bit indicated by the first sequence, flag the start/end of a frame, and
// signal an error on the third sequence. All outputs are active high,
// i.e. they go high for one clock cycle when the condition occurs.
module TopModule(
    input  clk,
    input  reset,
    input  in,
    output reg disc,
    output reg flag,
    output reg err
);
    reg [2:0] cnt;
    reg [2:0] state;
    always @(posedge clk) begin
        if (reset) begin
            state <= 3'b001;
            cnt <= 3'b000;
            disc <= 1'b0;
            flag <= 1'b0;
            err <= 1'b0;
        end else begin
            case (state)
                3'b001: begin
                    if (in) begin
                        state <= 3'b010;
                        cnt <= 3'b001;
                    end
                end
                3'b010: begin
                    if (in) begin
                        cnt <= cnt + 1'b1;
                        if (cnt == 3'b111) begin
                            state <= 3'b011;
                            cnt <= 3'b000;
                            disc <= 1'b1;
                        end
                    end else begin
                        state <= 3'b001;
                        cnt <= 3'b000;
                    end
                end
                3'b011: begin
                    if (in) begin
                        cnt <= cnt + 1'b1;
                        if (cnt == 3'b1111) begin
                            state <= 3'b100;
                            cnt <= 3'b000;
                            flag <= 1'b1;
                        end
                    end else begin
                        state <= 3'b001;
                        cnt <= 3'b000;
                    end
                end
                3'b100: begin
                    if (in) begin
                        cnt <= cnt + 1'b1;
                        if (cnt >= 3'b11111) err <= 1'b1;
                    end else begin
                        state <= 3'b001;
                        cnt <= 3'b000;
                    end
                end
            endcase
            if (disc) disc <= 1'b0;
            if (flag) flag <= 1'b0;
            if (err) err <= 1'b0;
        end
    end
endmodule

