// Moore-type finite state machine, synchronous (unpipelined) HDLC framing:
// discards the next bit after a flag (5 consecutive 1s), flags the start/end
// of a frame (6 consecutive 1s), and signals an error on 7 or more consecutive
// 1s.
module TopModule(input clk, input reset, input in, output reg disc, output reg flag, output reg err);
  reg [2:0] cnt;
  reg [2:0] cnt2;
  reg [2:0] cnt3;
  reg last;
  reg [1:0] state;
  always @(posedge clk) begin
    if (reset) begin
      state <= 2'b00;
      cnt <= 3'b000;
      cnt2 <= 3'b000;
      cnt3 <= 3'b000;
      last <= 1'b0;
      disc <= 1'b0;
      flag <= 1'b0;
      err <= 1'b0;
    end else begin
      case (state)
        2'b00: begin // looking for the first bit of a flag
          if (in) begin
            state <= 2'b01;
            cnt <= 3'b001;
          end else begin
            last <= in;
          end
        end
        2'b01: begin // looking for the second bit of a flag
          if (in) begin
            cnt <= cnt + 1;
            if (cnt == 3'b111) begin
              state <= 2'b10;
              cnt2 <= 3'b001;
              disc <= 1'b1;
            end
          end else begin
            state <= 2'b00;
            cnt <= 3'b000;
          end
        end
        2'b10: begin // looking for the rest of a flag (6 bits)
          if (in) begin
            cnt2 <= cnt2 + 1;
            if (cnt2 == 3'b110) begin
              state <= 2'b11;
              cnt3 <= 3'b001;
              flag <= 1'b1;
            end
          end else begin
            state <= 2'b00;
            cnt <= 3'b000;
          end
        end
        2'b11: begin // looking for the rest of a flag (7 or more bits)
          if (in) begin
            cnt3 <= cnt3 + 1;
            err <= 1'b1;
          end else begin
            state <= 2'b00;
            cnt <= 3'b000;
          end
        end
      endcase
    end
  end
endmodule

