module TopModule(input clk, input load, input [255:0] data, output [255:0] q);
    reg [255:0] r, r2;
    wire [255:0] n;
    genvar i, j;
    generate for (i = 0; i < 16; i = i + 1) begin : rows
        for (j = 0; j < 16; j = j + 1) begin : cols
            NeighbourCounter nc(.x(i), .y(j), .q(n[i*16 + j]));
        end
