// sensor change.
module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);
    reg [2:0] level;
    reg [2:0] last_level;
    always @(posedge clk) begin
        if (reset) begin
            level <= 3'b111;
            last_level <= 3'b000;
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b1;
        end else begin
            last_level <= level;
            case (s)
                3'b000: level <= 3'b000;
