                    done <= 1;
                    if (ack) begin
                        done <= 0;
                        state <= 2'b00;
                    end
                end
            endcase
            if (counter == duration) begin
                counter <= 4'b0000;
            end else begin
                counter <= counter + 1;
            end
        end
    end
